/**
 * Development-only: the agent's browser pane, mirrored read-only, so the
 * Cowork Output panel can show a web page being looked at (`?preview&rail=browser`).
 * The picture is an invented "acme-weather" status page, drawn once and embedded.
 */
import { useBrowserToolMirror } from '@/hooks/useBrowserToolMirror'

const PAGE = 'data:image/jpeg;base64,'

export function seedBrowserPane(sessionId: string) {
  useBrowserToolMirror.setState({
    byId: {
      [sessionId]: {
        url: 'http://localhost:5173/radar',
        title: 'Radar feed status - acme-weather',
        action: 'screenshot after the retry fix',
        screenshot: PAGE,
        tabs: [
          { id: 't1', title: 'Radar feed status', active: true },
          { id: 't2', title: 'acme-weather docs', active: false },
        ],
        // Far ahead, so the pane always reads as live while it is looked at.
        updatedAt: Date.now() + 3_600_000,
        frameAt: Date.now() + 3_600_000,
      },
    },
  } as never)
}
